package com.finanscore.scoring.config; import com.finanscore.motorscoring.application.service.*;import com.finanscore.motorscoring.application.usecase.*;import com.finanscore.motorscoring.domain.repository.*;import com.finanscore.motorscoring.domain.service.*;import com.finanscore.motorscoring.infrastructure.transaction.*;import org.springframework.beans.factory.annotation.Qualifier;import org.springframework.context.annotation.*;import org.springframework.transaction.*;import org.springframework.transaction.support.*;import java.time.Clock;
@Configuration public class ScoringBeans{@Bean Clock clock(){return Clock.systemUTC();}@Bean CalculadorCapacidadPago capacidad(){return new CalculadorCapacidadPago();}@Bean CalculadorRelacionDeudaIngreso relacion(){return new CalculadorRelacionDeudaIngreso();}@Bean CalculadorRelacionCuotaIngreso cuota(){return new CalculadorRelacionCuotaIngreso();}@Bean EvaluadorReglasExcluyentes excluyentes(){return new EvaluadorReglasExcluyentes();}@Bean CalculadorScoring calc(CalculadorCapacidadPago c,CalculadorRelacionDeudaIngreso r,CalculadorRelacionCuotaIngreso q,EvaluadorReglasExcluyentes e){return new CalculadorScoring(c,r,q,e);}@Bean(name="crearCore") CrearSolicitudCreditoUseCase crearCore(SolicitanteRepository s,SolicitudCreditoRepository q,ProductoCrediticioRepository p,Clock c){return new CrearSolicitudCreditoService(s,q,p,c);}@Bean @Primary CrearSolicitudCreditoUseCase crear(@Qualifier("crearCore")CrearSolicitudCreditoUseCase c,PlatformTransactionManager tm){return new TransactionalCrearSolicitudCreditoUseCase(c,new TransactionTemplate(tm));}@Bean(name="evalCore") EjecutarEvaluacionScoringUseCase evalCore(SolicitudCreditoRepository q,SolicitanteRepository s,ProductoCrediticioRepository p,ModeloScoringRepository m,EvaluacionCrediticiaRepository e,CalculadorScoring c,Clock clock){return new EjecutarEvaluacionScoringService(q,s,p,m,e,c,clock);}@Bean @Primary EjecutarEvaluacionScoringUseCase eval(@Qualifier("evalCore")EjecutarEvaluacionScoringUseCase c,PlatformTransactionManager tm){return new TransactionalEjecutarEvaluacionScoringUseCase(c,new TransactionTemplate(tm));}}
